=== FrostKnight
using System;
using Chaos.AnimatorExtensions;
using UnityEngine;
public class FrostKnight : Knight
{
	public class FrostKnightHurtState : EnemyHurtState
	{
		public new FrostKnight parent;
		public FrostKnightHurtState(string newName, FSM newFSM, FrostKnight newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
		}
		public override void OnEnter()
		{
			base.OnEnter();
			parent.DestroyBarrier();
		}
	}
	public class FrostKnightDeadState : EnemyDeadState
	{
		public new FrostKnight parent;
		public FrostKnightDeadState(string newName, FSM newFSM, FrostKnight newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
		}
		public override void OnEnter()
		{
			base.OnEnter();
			parent.DestroyBarrier();
		}
	}
	public class FrostKnightGuardState(string newName, FSM newFSM, FrostKnight newEnt) : State<FrostKnight>(newName, newFSM, newEnt)
	{
		private float knockbackPercentage = 0.35f;
		public string guardAnimName = "Block";
		public float animExitTime;
		private bool firstFrame;
		public override void OnEnter()
		{
			if (parent.health != null && parent.health.lastAttack != null)
			{
				parent.health.lastAttack.knockbackVector *= knockbackPercentage;
				parent.ApplyKnockback(parent.health.lastAttack);
				parent.FaceTarget(parent.health.lastAttack.attackerPosition, parent.animFacingDirections);
			}
			animExitTime = Mathf.Lerp(0.5f, 0.35f, parent.DifficultyValue);
			parent.anim.Play(guardAnimName, -1, 0f);
			firstFrame = true;
		}
		public override void Update()
		{
			if (firstFrame)
			{
				firstFrame = false;
			}
			else if (parent.anim.AnimPlayed(animExitTime))
			{
				parent.HandleExitTransitions(setAlert: true);
			}
		}
	}
	public class FrostKnightIceShieldState : SkillState
	{
		private NumVarStatMod shieldMod;
		private IceBarrier currentIB;
		private AudioSource formSFXSource;
		public new FrostKnight parent;
		public FrostKnightIceShieldState(string newName, FSM newFSM, FrostKnight newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD, newAuto)
		{
			parent = newEnt;
			requireLineOfSight = false;
			shieldMod = new NumVarStatMod(skillID, 0f, 10, VarStatModType.Override, fillToNewMax: true);
		}
		public override void OnEnter()
		{
			if (currentIB != null)
			{
				StartCooldown();
				ExitTransition();
				return;
			}
			base.OnEnter();
			parent.movement.EndMovement();
			parent.anim.Play("Block");
			windupTime = StdWindupTime * 1.5f;
			windupStopwatchID = ChaosStopwatch.Begin(windupTime);
			shieldMod.modValue = (int)Mathf.Lerp(75f, 125f, currentDiffValue);
			CreateBarrier();
		}
		public override void OnExit()
		{
			base.OnExit();
			if (formSFXSource != null)
			{
				formSFXSource.Stop();
			}
			if (!WindupCheck && currentIB != null)
			{
				currentIB.DestroyBarrier();
			}
		}
		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			DeactivatePowerUpEffect();
			parent.iceBarrier = currentIB;
			parent.health.shieldStat.AddMod(shieldMod);
			string audioID = "IceSolidify";
			Vector2? soundOrigin = parent.transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
		}
		public void CreateBarrier()
		{
			currentIB = ChaosInst<IceBarrier>(IceBarrier.Prefab, parent.leftHandTrans.position);
			currentIB.followTrans = parent.leftHandTrans;
			currentIB.formTime = windupTime;
			string audioID = "IceForm2";
			Vector2? soundOrigin = parent.transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
			formSFXSource = SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
		}
	}
	public class FrostKnightIceBashState : SkillState
	{
		private bool lungeComplete;
		private float lungeDelayTime = 0.5f;
		private int lungeDelayStopwatchID;
		private float lungeSpeed = 40f;
		private float lungeDuration = 0.15f;
		private NumVarStatMod dashSpeedMod;
		private NumVarStatMod dashDurationMod;
		private Attack atkCircle;
		private IcicleFormEffect icicleFormEffect;
		private Vector2 currentPosition;
		public new FrostKnight parent;
		public FrostKnightIceBashState(string newName, FSM newFSM, FrostKnight newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD, newAuto)
		{
			parent = newEnt;
			useTargetHurtBox = false;
			dashSpeedMod = new NumVarStatMod("dashOverride", lungeSpeed, 10, VarStatModType.OverrideWithMods);
			dashDurationMod = new NumVarStatMod("dashOverride", lungeDuration, 10, VarStatModType.OverrideWithMods);
		}
		public override void OnEnter()
		{
			base.OnEnter();
			parent.movement.EndMovement();
			parent.anim.Play("Forehand", -1, 0f);
			parent.movement.dashVector = targetVector;
			this.icicleFormEffect = PoolManager.GetPoolItem<IcicleFormEffect>();
			IcicleFormEffect icicleFormEffect = this.icicleFormEffect;
			int emitRate = 50;
			Transform leftHandTrans = parent.leftHandTrans;
			icicleFormEffect.Play(emitRate, -1f, -1f, -1f, leftHandTrans);
			parent.ToggleFloorContact(allyCollisionOn: false);
			lungeComplete = false;
			windupStopwatchID = ChaosStopwatch.Begin(StdWindupTime * 1.5f);
			currentPosition = parent.transform.position;
			ChaosInst<SnowTrail>(SnowTrail.Prefab).EmitTrail(currentPosition, currentPosition + targetVector * (lungeSpeed * lungeDuration), 30);
			string audioID = "IceForm";
			Vector2? soundOrigin = parent.transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
		}
		public override void Update()
		{
			if (lungeComplete && ChaosStopwatch.Check(lungeDelayStopwatchID))
			{
				ExitTransition();
			}
			else
			{
				if (WindupCheck)
				{
					return;
				}
				if (!ChaosStopwatch.Check(windupStopwatchID))
				{
					parent.anim.Play("Forehand", -1, 0f);
					return;
				}
				windupComplete = true;
				DeactivatePowerUpEffect();
				if (icicleFormEffect != null)
				{
					icicleFormEffect.Stop();
					icicleFormEffect = null;
				}
				atkCircle = ChaosInst<Attack>(Attack.CirclePrefab);
				atkCircle.SetAttackInfo(parent.skillCategory, skillID);
				atkCircle.knockbackOverwriteVector = targetVector;
				atkCircle.transform.localScale *= 2f;
				parent.movement.dashSpeedStat.AddMod(dashSpeedMod);
				parent.movement.dashDurationStat.AddMod(dashDurationMod);
				parent.movement.dashTimer = lungeDuration;
				parent.anim.Play("Forehand", -1, 0.5f);
				string audioID = "IceDash";
				Vector2? soundOrigin = parent.transform.position;
				float standardPitchRange = SoundManager.StandardPitchRange;
				SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
				audioID = "IceSolidify";
				soundOrigin = parent.transform.position;
				standardPitchRange = SoundManager.StandardPitchRange;
				SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
			}
		}
		public override void FixedUpdate()
		{
			if (WindupCheck && !lungeComplete && parent.movement.DashToTarget())
			{
				SetLungeComplete();
			}
		}
		public override void LateUpdate()
		{
			if (atkCircle != null)
			{
				atkCircle.transform.position = parent.transform.position;
			}
		}
		public override void OnExit()
		{
			base.OnExit();
			parent.ToggleFloorContact();
			parent.movement.dashSpeedStat.RemoveMod(dashSpeedMod.ID);
			parent.movement.dashDurationStat.RemoveMod(dashDurationMod.ID);
			parent.movement.EndMovement();
			if (icicleFormEffect != null)
			{
				icicleFormEffect.Stop();
				icicleFormEffect = null;
			}
			DestroyAttackCircle();
		}
		public void SetLungeComplete(Collider2D col = null)
		{
			lungeComplete = true;
			lungeDelayStopwatchID = ChaosStopwatch.Begin(lungeDelayTime);
			parent.movement.EndMovement();
