using System.Collections.Generic;
using Chaos.VectorExtensions;
using UnityEngine;
public class FrostArcher : Archer
{
	public class FrostArcherAttackState : ArcherAttackSkillState
	{
		private IceShard currentIS;
		private Dictionary<Vector3, Transform> projectilePositionDict = new Dictionary<Vector3, Transform>();
		private List<IceShard> projectileList = new List<IceShard>();
		public int projectileCount = 5;
		private int projectileCounter;
		private int projectileSpawnStopwatchID;
		private int projectileReleaseStopwatchID;
		public float projectileReleaseDelay = 0.2f;
		public new FrostArcher parent;
		public FrostArcherAttackState(string newName, FSM newFSM, FrostArcher newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
		}
		public override void SetVars()
		{
			projectilePrefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/IceArrow.prefab");
		}
		public IceShard CreateIceShard()
		{
			currentIS = base.CreateProjectile() as IceShard;
			currentIS.projectileLight.SetActive(value: false);
			currentIS.transform.SetParent(parent.arrowSpawn);
			currentIS.transform.localPosition = Vector3.right * (projectileCount - projectileCounter - 3) * 0.25f;
			projectilePositionDict[currentIS.transform.localPosition] = currentIS.transform;
			currentIS.attackWhileSpinning = false;
			currentIS.flashDuration = 0f;
			currentIS.Show();
			currentIS.playFormSound = false;
			return currentIS;
		}
		public override void HoldProjectile()
		{
			if (projectileList.Count > 0 && projectileList[0] != null)
			{
				parent.targetLine.transform.position = projectileList[0].transform.position;
			}
			foreach (KeyValuePair<Vector3, Transform> item in projectilePositionDict)
			{
				if (item.Value != null)
				{
					item.Value.localPosition = item.Key;
				}
			}
			foreach (IceShard projectile in projectileList)
			{
				if (projectile != null)
				{
					projectile.RefreshFlightTime();
				}
			}
		}
		public override void ReleaseProjectile()
		{
			currentIS = projectileList[projectileList.Count - 1];
			if (!(currentIS == null))
			{
				projectileList.Remove(currentIS);
				currentIS.transform.SetParent(null);
				currentIS.transform.localScale = Vector3.one;
				currentIS.PointIceShard(aimVector);
				currentIS.ReleaseIceShard(aimVector);
				currentIS.attackBox.knockbackOverwriteVector = aimVector;
				currentIS.moveSpeed = 40f;
				currentIS.flyTime = 0.4f;
				currentIS.InitTimers();
				SoundManager.PlayAudioWithDistance("FrostArcherIceArrow", parent.transform.position);
			}
		}
		public override void OnEnter()
		{
			base.OnEnter();
			projectileCounter = 0;
			chargeTime = 0.125f + StdWindupTime * 0.75f;
			projectileSpawnStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, chargeTime / (float)projectileCount, projectileCount);
		}
		public override void Update()
		{
			if (!projectileCreated)
			{
				parent.UpdateTargetInfo(parent.attackRadius * attackRangeModifier);
				if (parent.closestTargetInfo == null)
				{
					ExitTransition();
					return;
				}
				AimTowardsTarget();
				parent.anim.Play("AttackWindup", -1, (float)projectileCounter / (float)projectileCount);
				if (!parent.HandleExtraSkills(hasLOS: true, updateTarget: true, updateLOS: true))
				{
					switch (ChaosStopwatch.CheckInterval(projectileSpawnStopwatchID))
					{
					case StopwatchState.Ready:
						projectileList.Add(CreateIceShard());
						projectileCounter++;
						break;
					case StopwatchState.Done:
						projectileCreated = true;
						chargeDelayStopwatchID = ChaosStopwatch.Begin(chargeDelay);
						projectileReleaseStopwatchID = ChaosStopwatch.Begin(chargeDelay + projectileReleaseDelay, useInterval: true, projectileReleaseDelay, projectileCount);
						break;
					}
					if (!drawSoundPlayed && ChaosStopwatch.GetTimePercentage(chargeStopwatchID) > 0.25f)
					{
						drawSoundPlayed = true;
						SoundManager.PlayAudioWithDistance("ArcherAttackWindup", parent.transform.position);
					}
				}
			}
			else if (!projectileReleased)
			{
				if (!ChaosStopwatch.Check(chargeDelayStopwatchID))
				{
					AimTowardsTarget();
					return;
				}
				switch (ChaosStopwatch.CheckInterval(projectileReleaseStopwatchID))
				{
				case StopwatchState.Running:
					break;
				case StopwatchState.Ready:
					parent.targetLine.IsVisible(status: false);
					parent.anim.Play("AttackRelease", -1, 0.4f);
					ReleaseProjectile();
					break;
				case StopwatchState.Done:
					projectileReleased = true;
					attackDelayStopwatchID = ChaosStopwatch.Begin(attackDelay);
					break;
				}
			}
			else
			{
				HandleAttackExit();
			}
		}
		public override void OnExit()
		{
			currentProjectile = null;
			base.OnExit();
			if (!projectileReleased)
			{
				PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(5, parent.arrowSpawn.position);
				for (int i = 0; i < projectileList.Count; i++)
				{
					currentIS = projectileList[i];
					if (currentIS != null)
					{
						currentIS.transform.SetParent(null);
						Object.Destroy(currentIS.gameObject);
					}
				}
			}
			projectileList.Clear();
			projectilePositionDict.Clear();
		}
	}
	public class FrostArcherIceTrapState : SkillState
	{
		public int trapCount = 3;
		public float castRange = 3f;
		public float duration = 3f;
		public float armTime = 1f;
		private float trapThrowHeight;
		private float trapThrowTime;
		public float trapThrowSpeed = 5f;
		private IceTrap currentIT;
		private Vector2 currentPosition;
		private Vector2 throwPosition;
		public FrostArcherIceTrapState(string newName, FSM newFSM, Enemy newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD, newAuto)
		{
			requireLineOfSight = false;
			useTargetHurtBox = false;
		}
		public override void OnEnter()
		{
			base.OnEnter();
			parent.movement.EndMovement();
			parent.anim.Play("Throw", -1, 0f);
			windupStopwatchID = ChaosStopwatch.Begin(StdWindupTime);
		}
		public override void WindupUpdate()
		{
			parent.anim.Play("Throw", -1, 0f);
		}
		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			DeactivatePowerUpEffect();
			parent.anim.Play("Throw", -1, 0.5f);
			currentPosition = parent.transform.position;
			trapThrowTime = StdWindupTime * 1.5f;
			trapThrowHeight = Mathf.Lerp(1.75f, 2.5f, currentDiffValue);
			for (int i = 0; i < trapCount; i++)
			{
				currentIT = ChaosInst<IceTrap>(IceTrap.Prefab);
				currentIT.attack.SetAttackInfo(parent.skillCategory, skillID);
				currentIT.armTime = armTime;
				currentIT.duration = duration;
				currentIT.attackAllies = true;
				currentIT.throwScript.throwHeight = trapThrowHeight;
				currentIT.throwScript.moveSpeed = trapThrowSpeed;
				currentIT.throwScript.baseFlightTime = trapThrowTime;
				currentIT.throwScript.layerMask = ChaosCollisions.layerAll;
				switch (i)
				{
				case 1:
					throwPosition = currentPosition + castRange * (targetVector + Globals.GetPerpendicular(targetVector)).normalized;
					break;
				case 2:
					throwPosition = currentPosition + castRange * (targetVector + Globals.GetPerpendicular(targetVector, horizontal: false)).normalized;
					break;
				default:
					throwPosition = currentPosition + castRange * targetVector;
					break;
				}
				currentIT.throwScript.ThrowToTargetVector(throwPosition);
			}
		}
	}
	public class FrostArcherArrowShowerState : SkillState
	{
		private int arrowCount = 5;
		private float arrowInterval = 0.2f;
		private int arrowStopwatchID;
		private float arrowFallTime;
		private bool arrowsFired;
		private float randomOffset = 0.75f;
		private static GameObject iceArrowMedPrefab;
		private ArrowShower currentAS;
		public new FrostArcher parent;
		public FrostArcherArrowShowerState(string newName, FSM newFSM, FrostArcher newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD, newAuto)
		{
			parent = newEnt;
			requireLineOfSight = false;
			iceArrowMedPrefab = ChaosBundle.Get("Assets/Prefabs/Effects/IceArrowMed.prefab");
		}
		public override void OnEnter()
		{
			base.OnEnter();
			parent.movement.EndMovement();
			parent.anim.Play("ArrowShowerWindup");
			Vector3 rotationVector = Globals.GetRotationVector(Vector2.up);
			if (!parent.isFacingRight)
			{
				rotationVector.z *= -1f;
			}
			rotationVector.z += 90f;
			parent.bowArm.localEulerAngles = rotationVector;
			arrowFallTime = StdWindupTime * 1.5f;
			arrowStopwatchID = ChaosStopwatch.Begin(arrowInterval, useInterval: true, arrowInterval, arrowCount);
			arrowsFired = false;
		}
		public override void Update()
		{
			if (!arrowsFired)
			{
				switch (ChaosStopwatch.CheckInterval(arrowStopwatchID))
				{
				case StopwatchState.Running:
					break;
				case StopwatchState.Ready:
					if (parent.UpdateTargetInfo() == null)
					{
						arrowsFired = true;
						break;
					}
					FireArrow(parent.closestTargetInfo.position);
					parent.anim.Play("ArrowShowerRelease", -1, 0f);
					SoundManager.PlayAudioWithDistance("FrostArcherIceArrowShower", parent.transform.position);
					Object.Instantiate(iceArrowMedPrefab, parent.arrowSpawn.position, Quaternion.identity);
					break;
				case StopwatchState.Done:
					arrowsFired = true;
					exitStopwatchID = ChaosStopwatch.Begin(exitTime);
					parent.anim.Play("Idle");
					DeactivatePowerUpEffect();
					break;
				}
			}
			else if (ChaosStopwatch.Check(exitStopwatchID))
			{
				ExitTransition();
			}
		}
		public void FireArrow(Vector2 targetPosition)
		{
			GameObject prefab = ArrowShower.Prefab;
			float radius = randomOffset;
			currentAS = ChaosInst<ArrowShower>(prefab, targetPosition.Randomize(1f, radius, 0f));
			currentAS.fallTime = arrowFallTime;
			currentAS.attackBox.SetAttackInfo(parent.skillCategory, skillID);
		}
	}
	public override void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new IdleState("Idle", fsm, this));
		fsm.AddState(new GoBackState("GoBack", fsm, this));
		fsm.AddState(new ChaseState("Chase", fsm, this));
		fsm.AddState(new EnemyDeadState("Dead", fsm, this));
		fsm.AddState(new EnemyHurtState("Hurt", fsm, this));
		fsm.AddState(new EnemyFallState("Fall", fsm, this));
		fsm.AddState(new DashState("Dash", fsm, this, 1, 10, 0f, 5f, 3f)
		{
			dashAway = true,
			dashOverPits = true,
			randomOffSet = 1f,
			castingAnimName = "Dash"
		});
		attackSkillID = "FrostArcherAttack";
