		fsm.AddState(new FrostArcherArrowShowerState("FrostArcherArrowShower", fsm, this, 1, 5, 0f, attackRadius + 2f, 7f));
		fsm.AddState(new FrostArcherIceTrapState("FrostArcherIceTrap", fsm, this, 2, 7, 0f, attackRadius, 8f));
		fsm.ChangeState(fsm.defaultStateName);
	}
