using UnityEngine;
public class FrostMage : Mage
	public class FrostMageSpreadShotState : BaseSpreadShotState
		private float projectileSpeed = 20f;
		private float pointedTime = 0.25f;
		private int pointedStopwatchID;
		private bool queuePointed;
		public FrostMageSpreadShotState(string newName, FSM newFSM, Enemy newEnt)
			: base(newName, newFSM, newEnt)
			projectilePrefab = IceShard.Prefab;
			castingAnimName = "Backhand";
			projectileCount = 3;
		public override void OnEnter()
			holdTime = StdWindupTime * 0.5f;
			base.OnEnter();
		public override void InitalizeAttack()
			base.InitalizeAttack();
			queuePointed = false;
		public override bool CreateAllProjectiles()
			if (!base.CreateAllProjectiles())
				return false;
			if (!queuePointed)
				queuePointed = true;
				pointedStopwatchID = ChaosStopwatch.Begin(pointedTime);
				return false;
			if (!ChaosStopwatch.Check(pointedStopwatchID))
				return false;
			foreach (Projectile projectile in projectileList)
				if (!(projectile == null))
					((IceShard)projectile).PointIceShard(projectile.moveVector);
			return true;
		public override void FireProjectile(Projectile givenProj)
			if (!(givenProj == null))
				givenProj.moveSpeed = projectileSpeed;
				(givenProj as IceShard).ReleaseIceShard(givenProj.moveVector);
				CameraController.ShakeCamera(0.25f);
