			base.OnEnter();
			parent.movement.EndMovement();
			parent.anim.Play("Charging", -1, 0f);
			windupStopwatchID = ChaosStopwatch.Begin(StdWindupTime * 1.5f);
			CreateDagger();
			parent.targetLine.aimVector = targetVector;
			parent.targetLine.maxRange = 15f;
			lineColor.a = 0.75f;
			parent.targetLine.line.SetColors(lineColor, lineColor);
			parent.targetLine.IsVisible(status: true);
