			base.OnExit();
			parent.targetLine.IsVisible(status: false);
			if (!WindupCheck && currentID != null)
				currentID.ResetProjectile();
		public override void WindupUpdate()
			if (currentID != null)
				currentID.RefreshFlightTime();
				currentID.transform.position = parent.leftHandTrans.position;
			lineColor.a = 0.75f * (1f - ChaosStopwatch.GetTimePercentage(windupStopwatchID));
			parent.targetLine.line.SetColors(lineColor, lineColor);
		public override void ExecuteSkill()
			base.ExecuteSkill();
			DeactivatePowerUpEffect();
			parent.anim.PlayDirectional("Attack", -1, 0.9f);
			parent.targetLine.IsVisible(status: false);
			if (currentID != null)
				currentID.transform.position = parent.hurtBoxTransform.position;
				currentID.attackBox.enabled = true;
				currentID.moveVector = targetVector;
				currentID.isPointedAtMoveVector = false;
			string audioID = "StandardThrow";
			Vector2? soundOrigin = parent.transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
			audioID = "IceDaggerBasic";
			soundOrigin = parent.transform.position;
			standardPitchRange = SoundManager.StandardPitchRange;
		private void CreateDagger()
			currentID = ChaosInst<IceDaggerProjectile>(IceDaggerProjectile.Prefab, parent.leftHandTrans.position);
			currentID.attackBox.SetAttackInfo(parent.skillCategory, skillID);
			currentID.attackBox.enabled = false;
			currentID.transform.localEulerAngles = Globals.GetRotationVector((!parent.isFacingRight) ? Vector3.right : Vector3.left);
			currentID.Show();
