	public override void Awake()
		base.Awake();
		Attack attack = attackBox;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		Attack attack2 = attackBox;
		attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		atkObj = attackBox.gameObject;
	public override void Start()
		base.Start();
		if (spawnDelay > 0f)
			light.enabled = false;
			spawnMoveVector = moveVector;
			moveVector = Vector2.zero;
			spawnDelayTimer.SetDelay(spawnDelay);
			spawnDelayTimer.IsRunning = true;
			anim.Play("Form", -1, 0f);
		else
			HandleLight();
	private void HandleLight()
		if (!(light == null))
			light.enabled = useLight;
	public override void Update()
		if (spawnDelay > 0f && !spawnDelayDone)
			if (spawnDelayTimer.IsRunning)
				return;
			HandleLight();
			moveVector = spawnMoveVector;
			RefreshFlightTime();
			Release();
			spawnDelayDone = true;
		base.Update();
	public override void FixedUpdate()
		base.FixedUpdate();
		if (!targetHit)
			return;
		switch (ChaosStopwatch.CheckInterval(hitCDStopwatchID))
		case StopwatchState.Running:
			SetAttackCol(givenStatus: false);
			break;
		case StopwatchState.Ready:
			SetAttackCol(givenStatus: true);
			CreateSpinEffect();
			if (!ChaosStopwatch.IntervalIsActive(hitCDStopwatchID))
				attackBox.ChangeAttackInfoLevel(2);
			break;
		case StopwatchState.Done:
			SetAttackCol(givenStatus: false);
			ResetProjectile();
			break;
