			parent.anim.Play("Form", -1, 0f);
			parent.spriteMat.SetColor("_FlashColor", Color.white);
		public override void Update()
			if (parent.anim.AnimPlayed())
				fsm.ChangeState(fsm.defaultStateName);
			else if (parent.anim.AnimPlayed(0.5f))
				parent.spriteMat.SetFloat("_FlashAmount", Mathf.Lerp(1f, 0f, parent.anim.GetAnimTime() * 2f - 1f));
	public class IdleState : State<IceDecoy>
		public IdleState(string stateName, FSM parentFSM, IceDecoy parentEntity)
			: base(stateName, parentFSM, parentEntity)
		public override void OnEnter()
			parent.anim.Play("Idle");
	public new class DeadState : State<IceDecoy>
		public DeadState(string stateName, FSM parentFSM, IceDecoy parentEntity)
			: base(stateName, parentFSM, parentEntity)
		public override void OnEnter()
			if (parent.health.lastAttack != null && Vector2.Distance(parent.transform.position, parent.health.lastAttack.attackerPosition) < 3.5f)
				parent.attack.transform.position = parent.health.lastAttack.attackerPosition;
			parent.anim.Play("Dead");
			if (parent.parentGroup != null)
				parent.parentGroup.Remove(parent.gameObject);
