				holdTime = StdWindupTime * 0.5f;
			}
			waveCountdown = waveCount - 1;
			attackInitalized = false;
		}
	}
	public virtual void InitalizeAttack()
	{
		projectileList.Clear();
		projectilesCreated = false;
		projectilesFired = false;
		castStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, castTime / (float)projectileCount, projectileCount);
		positionCount = totalPositionCount - (int)((float)projectileCount * 0.5f);
	}
	public override void ExecuteSkill()
	{
		if (!attackInitalized)
		{
			if (trackTarget && !TargetFound())
			{
				base.ExecuteSkill();
				return;
			}
			attackInitalized = true;
			InitalizeAttack();
		}
		if (!projectilesCreated)
		{
			parent.anim.Play(castingAnimName, -1, 0f);
			if (CreateAllProjectiles())
			{
				projectilesCreated = true;
				holdStopwatchID = ChaosStopwatch.Begin(holdTime);
			}
			return;
		}
		if (!projectilesFired)
		{
			if (!ChaosStopwatch.Check(holdStopwatchID))
			{
				OnProjectileHold();
				return;
			}
			projectilesFired = true;
			FireAllProjectiles();
			if (!loopingCastingAnim)
			{
				parent.anim.Play(castingAnimName, -1, 1f);
			}
			waveStopwatchID = ChaosStopwatch.Begin(waveTime);
		}
		if (waveCountdown > 0)
		{
			if (ChaosStopwatch.Check(waveStopwatchID))
			{
				waveCountdown--;
				attackInitalized = false;
			}
		}
		else
		{
			base.ExecuteSkill();
		}
	}
	public override void ExitTransition()
	{
		if (fsm.HasState("Reposition"))
